#define CONTROLLED_READOUT_LIBRARY
#include "train_controlled_readout.cu"
#include <set>
#include <map>
int main(int argc,char**argv){try{if(argc!=2)return 1;std::string root=argv[1];ServerCore core;if(!core.load("tao_fixed_step50002.bin","tao_context_supported.tcg","tao_coef_rts1_128.reader","tinystories_train.txt","experiments/d256_nibble64_baseline/train_tokens.bin"))return 2;std::set<std::array<int32_t,64>> training;Data train;double feature_error=0;for(int split=0;split<3;++split){auto data=load(root+(split==0?"/train.bin":split==1?"/test_context.bin":"/test_unseen_answers.bin"),core);std::map<std::pair<int,int>,int>counts;for(size_t n=0;n<data.records.size();++n){const auto&r=data.records[n];if(r.input[63]<900||r.input[63]>906)throw std::runtime_error("query");counts[{r.distance,r.target}]++;if(split==0)training.insert(r.input);else if(training.count(r.input))throw std::runtime_error("overlap");if(n%2==0){if(n+1>=data.records.size())throw std::runtime_error("odd pairs");auto&b=data.records[n+1];if(r.pair!=b.pair||r.target!=b.alternate||r.alternate!=b.target||r.distance!=b.distance)throw std::runtime_error("pair metadata");int diff=0;for(int j=0;j<64;++j)if(r.input[j]!=b.input[j]){++diff;if(j!=63-r.distance||r.input[j]!=r.target||b.input[j]!=b.target)throw std::runtime_error("pair key");}if(diff!=(r.distance<64?1:0))throw std::runtime_error("pair differences");}
std::array<std::array<int,256>,65> prefix{};uint32_t hash=5381;for(int t=0;t<64;++t){auto code=core.q1.code(r.input[t]);for(int d=0;d<256;++d){int v=prefix[t][d]+code[d];while(v>1)v-=3;while(v< -1)v+=3;prefix[t+1][d]=v;}hash=hash*33+uint32_t(r.input[t]);}for(int d=0;d<256;++d){float v=0;for(int k=0;k<=16;++k)v+=core.reader_sel[k*256+d]*prefix[64-k][d];feature_error=std::max(feature_error,double(std::abs(v-data.x[n*Features+d])));}for(int j=0;j<64;++j)feature_error=std::max(feature_error,double(std::abs(float((hash>>(4*(j&7)))&15)/15-.5f-data.x[n*Features+256+j])));if(data.x[n*Features+320]!=1)throw std::runtime_error("bias feature");}for(int d:{2,4,8,15,16,32,64})for(int label=(split==2?144:128);label<(split==2?160:144);++label)if(counts[{d,label}]!=(split==0?64:16))throw std::runtime_error("balance");printf("PASS dataset split=%d records=%zu balanced pairs overlap checked\n",split,data.records.size());if(split==0)train=std::move(data);}if(feature_error!=0)throw std::runtime_error("prefix feature oracle");printf("PASS independent saved-prefix feature max_abs=%.9g all10752records\n",feature_error);
int rows=int(train.y.size());auto dx=device(train.x);auto dy=device(train.y);float* dz;check(cudaMalloc(&dz,rows*Classes*sizeof(float)));for(int seed:{42,123,2026}){std::vector<float>w(Classes*Features);std::ifstream in(root+"/readout_seed"+std::to_string(seed)+".bin",std::ios::binary);in.read((char*)w.data(),w.size()*4);if(!in)throw std::runtime_error("weights");auto dw=device(w);predict<<<(rows*Classes+255)/256,256>>>(dx,dw,dz,rows);std::vector<float>gpu(rows*Classes),cpu(gpu.size());check(cudaMemcpy(gpu.data(),dz,gpu.size()*4,cudaMemcpyDeviceToHost));double err=0;for(int n=0;n<rows;++n)for(int c=0;c<Classes;++c){float value=0;for(int f=0;f<Features;++f)value+=w[c*Features+f]*train.x[n*Features+f];cpu[n*Classes+c]=value;err=std::max(err,double(std::abs(value-gpu[n*Classes+c])));}if(err>1e-5)throw std::runtime_error("posttraining logits");printf("PASS seed=%d posttraining logits max_abs=%.9g rows=%d\n",seed,err,rows);
const int probe=64;residual<<<1,128>>>(dz,dy,probe);update<<<(Classes*Features+255)/256,256>>>(dw,dx,dz,probe);std::vector<float>actual(w.size());check(cudaMemcpy(actual.data(),dw,actual.size()*4,cudaMemcpyDeviceToHost));std::vector<double>res(probe*Classes);for(int n=0;n<probe;++n){double mx=*std::max_element(cpu.begin()+n*Classes,cpu.begin()+(n+1)*Classes),sum=0;for(int c=0;c<Classes;++c)sum+=std::exp(double(cpu[n*Classes+c])-mx);for(int c=0;c<Classes;++c)res[n*Classes+c]=std::exp(double(cpu[n*Classes+c])-mx)/sum-double(c==train.y[n]);}double update_error=0;for(int c=0;c<Classes;++c)for(int f=0;f<Features;++f){double grad=0;for(int n=0;n<probe;++n)grad+=res[n*Classes+c]*train.x[n*Features+f];double expected=w[c*Features+f]-.05*(grad/probe+.001*w[c*Features+f]);update_error=std::max(update_error,std::abs(expected-actual[c*Features+f]));}if(update_error>1e-6)throw std::runtime_error("gradient update oracle");printf("PASS seed=%d independent double CPU gradient update max_abs=%.9g rows=%d\n",seed,update_error,probe);check(cudaFree(dw));}check(cudaFree(dx));check(cudaFree(dy));check(cudaFree(dz));return 0;}catch(const std::exception&e){fprintf(stderr,"FAIL %s\n",e.what());return 10;}}
